// реєстрація користувачів для статичних даних: прогалина, яку показав
// звіт мутацій (перевірки імені й ролі не виконувались жодним тестом)
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';

import {
  Role,
  createIdentityService,
  createMemoryIdentityRepository,
} from '../../src/identity/index.js';

const service = () =>
  createIdentityService({ identityRepository: createMemoryIdentityRepository() });

describe('identityService.register', () => {
  test("ім'я обрізається і зберігається", async () => {
    const user = await service().register({
      fullName: '  Ірина Коваль  ',
      role: Role.RESIDENT,
      verifiedAt: null,
      taxIdHash: 'h',
    });

    assert.equal(user.fullName, 'Ірина Коваль');
  });

  test("порожнє ім'я і невідома роль відхиляються", async () => {
    const identity = service();

    await assert.rejects(
      identity.register({
        fullName: '   ',
        role: Role.RESIDENT,
        verifiedAt: null,
        taxIdHash: 'h',
      }),
      { code: 'domain_error' },
    );
    await assert.rejects(
      identity.register({
        fullName: 'Хтось',
        role: /** @type {import('../../src/identity/index.js').Role} */ ('guest'),
        verifiedAt: null,
        taxIdHash: 'h',
      }),
      { code: 'domain_error' },
    );
  });
});

test/unit/cycles.test.js.source:
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';

import {
  Category,
  CycleError,
  Phase,
  makeCategoryLimit,
  makeCycle,
  phaseAt,
} from '../../src/cycles/index.js';
import {
  IN_RESULTS,
  IN_REVIEW,
  IN_SUBMISSION,
  IN_VOTING,
  T0,
  testCycle,
} from '../helpers.js';

describe('[AC-1.7] раунд', () => {
  test('фаза визначається датами раунду', () => {
    const cycle = testCycle();
    const cases = [
      [new Date(T0.getTime() - 1000), Phase.PLANNED],
      [T0, Phase.SUBMISSION],
      [IN_SUBMISSION, Phase.SUBMISSION],
      [IN_REVIEW, Phase.REVIEW],
      [IN_VOTING, Phase.VOTING],
      [IN_RESULTS, Phase.RESULTS],
    ];
    for (const [moment, phase] of cases) {
      assert.equal(phaseAt(cycle, /** @type {Date} */ (moment)), phase);
    }
  });

  test('фази не можуть перекриватися', () => {
    const cycle = testCycle();
    assert.throws(
      () =>
        makeCycle({
          ...cycle,
          id: 2,
          submissionTo: cycle.votingFrom,
          votingFrom: cycle.submissionTo,
          limits: [...cycle.limits],
        }),
      CycleError,
    );
  });

  test('максимальна вартість не більша за бюджет категорії', () => {
    assert.throws(() => makeCategoryLimit(Category.SMALL, 100, 101), CycleError);
  });

  test('назва раунду не може бути порожньою', () => {
    const cycle = testCycle();
    assert.throws(
      () => makeCycle({ ...cycle, title: '  ', limits: [...cycle.limits] }),
      CycleError,
    );
  });

  test('категорія ліміту лише small або large', () => {
    assert.throws(
      () =>
        makeCategoryLimit(
          /** @type {'small'} */ (/** @type {unknown} */ ('medium')),
          100,
          10,
        ),
      CycleError,
    );
  });
});

